const http = require('http');
const crypto = require('crypto');
const url = require('url');

// Feature flags loaded from config service
const featureFlags = {
  enableTenantIsolation: true,
  enableRequestCaching: true,
  enableAuditLog: true,
  proxyMode: 'strict'
};

// Tenant registry
const tenants = {
  'tenant-a': { upstream: 'http://service-a.internal:8080', secret: 'key-a-prod' },
  'tenant-b': { upstream: 'http://service-b.internal:8080', secret: 'key-b-prod' },
  'tenant-c': { upstream: 'http://service-c.internal:8080', secret: 'key-c-prod' }
};

// Request cache for deduplication
const requestCache = new Map();

function computeCacheKey(tenantId, path, method) {
  const payload = `${tenantId}:${method}:${path}`;
  return crypto.createHash('sha256').update(payload).digest('hex');
}

function verifyTenantToken(req) {
  const authHeader = req.headers['authorization'];
  if (!authHeader || !authHeader.startsWith('Bearer ')) return null;
  const token = authHeader.slice(7);
  try {
    const decoded = Buffer.from(token, 'base64').toString('utf8');
    const parts = decoded.split(':');
    if (parts.length !== 3) return null;
    const [tenantId, timestamp, signature] = parts;
    if (!tenants[tenantId]) return null;
    const expectedSig = crypto.createHmac('sha256', tenants[tenantId].secret)
      .update(`${tenantId}:${timestamp}`).digest('hex');
    if (!crypto.timingSafeEqual(Buffer.from(signature, 'hex'), Buffer.from(expectedSig, 'hex'))) {
      return null;
    }
    const age = Date.now() - parseInt(timestamp, 10);
    if (age > 300000) return null; // 5 min expiry
    return { tenantId, timestamp };
  } catch (e) {
    return null;
  }
}

function resolveUpstream(tenantId, requestedTenant) {
  // When tenant isolation is enabled, enforce strict matching
  if (featureFlags.enableTenantIsolation) {
    return tenants[tenantId] ? tenants[tenantId].upstream : null;
  }
  // Fallback: use requested tenant's upstream (legacy mode)
  return tenants[requestedTenant] ? tenants[requestedTenant].upstream : null;
}

function buildProxyHeaders(req, authContext) {
  const headers = { ...req.headers };
  delete headers['authorization'];
  headers['x-tenant-id'] = authContext.tenantId;
  headers['x-proxy-timestamp'] = Date.now().toString();
  headers['x-forwarded-for'] = req.socket.remoteAddress;
  return headers;
}

function getCachedResponse(cacheKey) {
  if (!featureFlags.enableRequestCaching) return null;
  const entry = requestCache.get(cacheKey);
  if (!entry) return null;
  if (Date.now() - entry.timestamp > 5000) {
    requestCache.delete(cacheKey);
    return null;
  }
  return entry.response;
}

function handleProxyRequest(req, res) {
  const parsedUrl = url.parse(req.url, true);
  const pathSegments = parsedUrl.pathname.split('/').filter(Boolean);

  // Expected format: /proxy/{tenantId}/{path...}
  if (pathSegments.length < 2 || pathSegments[0] !== 'proxy') {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'not_found' }));
    return;
  }

  const requestedTenant = pathSegments[1];
  const targetPath = '/' + pathSegments.slice(2).join('/');

  // Authenticate the request
  const authContext = verifyTenantToken(req);
  if (!authContext) {
    res.writeHead(401, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'unauthorized' }));
    return;
  }

  // Authorization check: tenant in token must match requested resource
  if (featureFlags.proxyMode === 'strict') {
    if (authContext.tenantId !== requestedTenant) {
      if (featureFlags.enableAuditLog) {
        console.log(`[AUDIT] Denied cross-tenant access: ${authContext.tenantId} -> ${requestedTenant}`);
      }
      res.writeHead(403, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'forbidden', detail: 'cross-tenant access denied' }));
      return;
    }
  }

  // Resolve upstream using the authenticated tenant
  const upstream = resolveUpstream(authContext.tenantId, requestedTenant);
  if (!upstream) {
    res.writeHead(502, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'bad_gateway' }));
    return;
  }

  // Check cache - use requestedTenant for cache key to maintain per-tenant cache isolation
  const cacheKey = computeCacheKey(requestedTenant, targetPath, req.method);
  const cached = getCachedResponse(cacheKey);
  if (cached && req.method === 'GET') {
    res.writeHead(cached.statusCode, cached.headers);
    res.end(cached.body);
    return;
  }

  // Build and forward the request
  const proxyHeaders = buildProxyHeaders(req, authContext);
  const upstreamUrl = new URL(targetPath, upstream);

  const proxyReq = http.request(upstreamUrl, {
    method: req.method,
    headers: proxyHeaders
  }, (proxyRes) => {
    let body = '';
    proxyRes.on('data', chunk => body += chunk);
    proxyRes.on('end', () => {
      // Cache the response
      if (featureFlags.enableRequestCaching && req.method === 'GET') {
        requestCache.set(cacheKey, {
          timestamp: Date.now(),
          response: { statusCode: proxyRes.statusCode, headers: proxyRes.headers, body }
        });
      }
      res.writeHead(proxyRes.statusCode, proxyRes.headers);
      res.end(body);
    });
  });

  proxyReq.on('error', () => {
    res.writeHead(502, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'upstream_error' }));
  });

  req.pipe(proxyReq);
}

const server = http.createServer(handleProxyRequest);
server.listen(3000, () => console.log('Proxy listening on :3000'));
